referenceSolutions.javascript:
export function kClosest(points            , k        )             {
  return points.map(point => [...point]).sort((a,b) => (a[0]*a[0]+a[1]*a[1])-(b[0]*b[0]+b[1]*b[1]) || a[0]-b[0] || a[1]-b[1]).slice(0,k);
}

